from .repository import balance, begin_immediate, move


def _check_amount(amount):
    if isinstance(amount, bool) or not isinstance(amount, int) or amount <= 0:
        raise ValueError("amount must be a positive integer")


def transfer(connection, publisher, source, target, amount):
    _check_amount(amount)
    if source == target:
        raise ValueError("source and target must differ")

    try:
        # Take the write lock before reading balances so the checks and the
        # writes see the same state. Callers are idle at entry, so the rollback
        # below only discards this transfer's own work.
        begin_immediate(connection)
        source_balance = balance(connection, source)
        if source_balance is None:
            raise ValueError(f"unknown source account: {source!r}")
        if balance(connection, target) is None:
            raise ValueError(f"unknown target account: {target!r}")
        if amount > source_balance:
            raise ValueError("amount exceeds source balance")
        move(connection, source, target, amount)
        connection.commit()
    except BaseException:
        connection.rollback()
        raise

    # Publish only after a successful commit. If publishing fails, the error
    # propagates but the committed transfer is left in place.
    publisher.publish({"source": source, "target": target, "amount": amount})
